def fizzline(n):
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

function backoffSeconds(attempt: number, base: number): number {
  return base * Math.pow(2, attempt);
}
